using System;
using System.Linq;
using System.IO;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Threading;
using System.Speech.Recognition;
using System.Speech.Synthesis;
namespace MacFlow
{
    internal sealed class AssistantWindow : Window
    {
        private readonly Desktop desktop;private WindowEntry target;private readonly TextBox input;private readonly TextBlock answer,destination;private readonly Button confirm,microphone;private Action pending;private SpeechRecognitionEngine recognizer;private SpeechSynthesizer speaker;private readonly DispatcherTimer listening=new DispatcherTimer{Interval=TimeSpan.FromSeconds(12)},appearance=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(820)},completion=new DispatcherTimer{Interval=TimeSpan.FromSeconds(5.2)};private bool closed,busy;private int operation;internal Func<WindowEntry,Task<string>> ReadPage=BrowserVisibleText.Read;
        internal AssistantWindow(Desktop controller,WindowEntry source)
        {
            desktop=controller;target=source;Title="MacFlow · Asistente";Width=550;Height=360;WindowStyle=WindowStyle.None;ResizeMode=ResizeMode.NoResize;ShowInTaskbar=false;Topmost=true;Background=Brushes.Transparent;
            var root=new DockPanel();var header=new DockPanel();var close=Design.Circle("close",delegate{Design.Dismiss(this);},"Cerrar asistente");DockPanel.SetDock(close,Dock.Right);header.Children.Add(close);var name=new StackPanel();name.Children.Add(Design.Text("¿Qué necesitás?",25,true));var caption=Design.Text("Escribí una orden o usá tu voz.",12,false);caption.SetResourceReference(TextBlock.ForegroundProperty,"GlassMuted");caption.Margin=new Thickness(0,7,0,0);name.Children.Add(caption);header.Children.Add(name);DockPanel.SetDock(header,Dock.Top);root.Children.Add(header);
            var footer=new StackPanel();destination=Design.Text("",11,false);destination.TextWrapping=TextWrapping.Wrap;destination.Margin=new Thickness(0,0,0,10);footer.Children.Add(destination);var actions=new StackPanel{Orientation=Orientation.Horizontal};microphone=Design.Button("Hablar",Listen,false);actions.Children.Add(microphone);actions.Children.Add(Design.Button("Detener voz",StopVoice,false));actions.Children.Add(Design.Button("Leer texto",delegate{Speak(input.Text);},false));footer.Children.Add(actions);var row=new DockPanel{Margin=new Thickness(0,12,0,0)};var send=Design.Button("Enviar",async delegate{await Execute(input.Text);},true);DockPanel.SetDock(send,Dock.Right);row.Children.Add(send);input=new TextBox{FontSize=15,Padding=new Thickness(12,10,12,10),MaxLength=4000,Background=Design.Brush("#16FFFFFF"),BorderThickness=new Thickness(0)};input.SetResourceReference(Control.ForegroundProperty,"GlassInk");input.SetResourceReference(TextBox.CaretBrushProperty,"GlassInk");System.Windows.Automation.AutomationProperties.SetName(input,"Orden para MacFlow");row.Children.Add(input);footer.Children.Add(row);DockPanel.SetDock(footer,Dock.Bottom);root.Children.Add(footer);
            var content=new StackPanel{Margin=new Thickness(0,24,0,18)};answer=Design.Text("Abrí Chrome · Buscá el clima · Minimizá Chrome\nEscribí hola · Leeme",15,false);answer.TextWrapping=TextWrapping.Wrap;content.Children.Add(answer);confirm=Design.Button("Confirmar acción",delegate{var action=pending;pending=null;confirm.Visibility=Visibility.Collapsed;if(action!=null)action();},true);confirm.Visibility=Visibility.Collapsed;confirm.Margin=new Thickness(0,18,0,0);content.Children.Add(confirm);root.Children.Add(new ScrollViewer{Content=content,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});Content=Design.Glass(root,28,false);
            SourceInitialized+=delegate{Native.Glass(this,Design.Dark);};Loaded+=delegate{if(!desktop.IsTesting)input.Focus();};KeyDown+=async delegate(object s,KeyEventArgs e){if(e.Key==Key.Enter){e.Handled=true;await Execute(input.Text);}else if(e.Key==Key.Escape){e.Handled=true;Design.Dismiss(this);}};
            listening.Tick+=delegate{StopListening();Say("No escuché una orden. Podés intentarlo otra vez.");};appearance.Tick+=delegate{appearance.Stop();Listen();};completion.Tick+=delegate{if(busy||desktop.AssistantListening||desktop.AssistantSpeaking)return;completion.Stop();desktop.SetAssistantVisual(AssistantStage.Hidden,null);};Closed+=delegate{closed=true;appearance.Stop();completion.Stop();StopListening();StopVoice();desktop.SetAssistantVisual(AssistantStage.Hidden,null);if(recognizer!=null)recognizer.Dispose();if(speaker!=null){speaker.SpeakAsyncCancelAll();speaker.Dispose();}};SetTarget(source);
        }
        internal void BeginFromIsland(){if(closed)return;StopAllVoice();pending=null;confirm.Visibility=Visibility.Collapsed;Hide();desktop.SetAssistantVisual(AssistantStage.Appearance,"");SoundCue.Play("open");appearance.Stop();appearance.Start();}
        internal void ShowInput(){if(closed)return;appearance.Stop();StopListening();if(!IsVisible){DisplaySpace.Center(this,.16);Show();Design.Reveal(this);}desktop.UpdateVoiceWake();desktop.UpdateAssistantEdge();if(!desktop.IsTesting){Activate();input.Focus();}}
        internal void SetTarget(WindowEntry source){target=source;destination.Text=source==null?"Para escribir o leer Chrome, abrí el asistente desde la barra con esa ventana activa.":"Ventana elegida: "+source.Title;}
        private void Say(string text){answer.Text=text;desktop.SetAssistantVisual(AssistantStage.Answer,text);completion.Stop();completion.Start();if(!desktop.IsTesting)SoundCue.Play("done");}
        internal async Task Execute(string command)
        {
            if(closed||busy)return;pending=null;confirm.Visibility=Visibility.Collapsed;var request=LocalCommands.Parse(command);int token=++operation;busy=true;completion.Stop();desktop.SetAssistantVisual(AssistantStage.Working,"Procesando la orden…");
            try
            {
                if(request.Intent==LocalIntent.Open){if(LocalCommands.Normalize(request.Argument)=="gemini"){LocalCommands.OpenChrome(LocalCommands.ChromePath(desktop.Apps),new Uri("https://gemini.google.com/app"));Say("Gemini abierto en Chrome. Iniciá sesión si lo solicita.");return;}var key=LocalCommands.Normalize(request.Argument);var candidates=desktop.Apps.Where(a=>LocalCommands.Normalize(a.Name).Contains(key)).Take(3).ToArray();var exact=candidates.FirstOrDefault(a=>LocalCommands.Normalize(a.Name)==key);if(exact!=null)candidates=new[]{exact};if(candidates.Length!=1){Say(candidates.Length==0?"No encontré esa aplicación. Probá su nombre completo.":"Hay varias coincidencias: "+String.Join(", ",candidates.Select(a=>a.Name))+". Usá el nombre completo.");return;}desktop.Launch(candidates[0]);Say("Abriendo "+candidates[0].Name+".");}
                else if(request.Intent==LocalIntent.Search){LocalCommands.OpenChrome(LocalCommands.ChromePath(desktop.Apps),LocalCommands.SearchUri(request.Argument));Say("Búsqueda abierta en Chrome. Cuando esté lista, reabrí el asistente desde la barra y pedí Leeme. La disponibilidad del resumen de IA depende de Google.");}
                else if(request.Intent==LocalIntent.Gemini){LocalCommands.OpenChrome(LocalCommands.ChromePath(desktop.Apps),new Uri("https://gemini.google.com/app"));Say("Gemini abierto. Podés escribir tu consulta allí. MacFlow no simula respuestas ni envía consultas a una API.");}
                else if(request.Intent==LocalIntent.Write){if(!Native.Matches(target)){Say("Primero elegí la ventana de destino abriendo el asistente desde la barra.");return;}var chosen=target;string text=request.Argument;answer.Text="Escribir en "+chosen.Title+":\n"+text;Confirm(async delegate{bool ok=await LocalTextInput.Write(chosen,text);if(!closed)Say(ok?"Texto enviado a la ventana elegida.":"No pude escribir: Windows bloqueó la entrada o cambió la ventana activa.");});}
                else if(request.Intent==LocalIntent.Minimize||request.Intent==LocalIntent.Close){var key=LocalCommands.Normalize(request.Argument);var windows=desktop.Windows.Where(w=>Native.Matches(w)&&(key=="ventana"||key=="esta ventana"?target!=null&&w.Handle==target.Handle:LocalCommands.Normalize(w.Title+" "+Path.GetFileNameWithoutExtension(w.Executable??"")).Contains(key))).ToArray();if(windows.Length!=1){Say("Elegí una ventana con su nombre completo. Encontré "+windows.Length+" coincidencias.");return;}var chosen=windows[0];if(request.Intent==LocalIntent.Minimize){desktop.MinimizeWindow(chosen);Say("Minimizando la ventana.");}else{answer.Text="¿Cerrar "+chosen.Title+"? La app puede pedirte guardar cambios.";Confirm(delegate{desktop.CloseWindow(chosen);Say("Cierre solicitado a la aplicación.");});}}
                else if(request.Intent==LocalIntent.Read){answer.Text="Leyendo el texto accesible de Chrome…";desktop.SetAssistantVisual(AssistantStage.Working,answer.Text);string text=await ReadPage(target);if(!closed&&token==operation){Say(text);Speak(text);}}
                else if(request.Intent==LocalIntent.Control)desktop.OpenControl();else if(request.Intent==LocalIntent.Settings)desktop.OpenSettings();else if(request.Intent==LocalIntent.Tasks)desktop.OpenTaskManager();
                else if(request.Intent==LocalIntent.VolumeUp||request.Intent==LocalIntent.VolumeDown){using(var backend=new ControlBackend()){var state=backend.Sound();if(!state.Available)throw new IOException("No hay salida de audio.");double value=Math.Max(0,Math.Min(100,state.Volume+(request.Intent==LocalIntent.VolumeUp?10:-10)));backend.Volume(value);Say("Volumen · "+(int)value+"%.");}}
                else Say("No entendí la orden. Uso comandos locales para abrir apps, buscar en Chrome, escribir, leer, minimizar y cerrar con confirmación. No ejecuto código ni órdenes de terminal.");
            }catch(Exception ex){if(!closed&&token==operation){Say(ex.Message);ShowInput();}}finally{if(token==operation){busy=false;if(!closed&&desktop.AssistantMode==AssistantStage.Working)Say("Listo.");}}
        }
        private void Confirm(Action action){pending=action;confirm.Visibility=Visibility.Visible;desktop.SetAssistantVisual(AssistantStage.Answer,"Revisá y confirmá la acción.");ShowInput();}
        private void Speak(string text){if(String.IsNullOrWhiteSpace(text)||desktop.IsTesting)return;try{if(speaker==null){speaker=new SpeechSynthesizer();speaker.StateChanged+=delegate(object s,System.Speech.Synthesis.StateChangedEventArgs e){if(!closed&&!Dispatcher.HasShutdownStarted)Dispatcher.BeginInvoke(new Action(delegate{if(!closed)desktop.SetAssistantSpeaking(speaker.State==SynthesizerState.Speaking&&desktop.AssistantMode!=AssistantStage.Hidden);}));};var voice=speaker.GetInstalledVoices().FirstOrDefault(v=>v.Enabled&&v.VoiceInfo.Culture.TwoLetterISOLanguageName=="es");if(voice!=null)speaker.SelectVoice(voice.VoiceInfo.Name);}speaker.SpeakAsyncCancelAll();speaker.SpeakAsync(text.Substring(0,Math.Min(6000,text.Length)));}catch(Exception ex){answer.Text="La voz de Windows no está disponible: "+ex.Message;}}
        private void Listen()
        {
            if(desktop.IsTesting)return;if(listening.IsEnabled){StopListening();desktop.SetAssistantVisual(AssistantStage.Hidden,null);return;}try{if(recognizer==null){var info=SpeechRecognitionEngine.InstalledRecognizers().FirstOrDefault(r=>r.Culture.TwoLetterISOLanguageName=="es");if(info==null)throw new IOException("No hay reconocimiento de voz español instalado. Podés seguir usando órdenes escritas.");recognizer=new SpeechRecognitionEngine(info);recognizer.LoadGrammar(new DictationGrammar());recognizer.SetInputToDefaultAudioDevice();recognizer.SpeechRecognized+=delegate(object s,SpeechRecognizedEventArgs e){Dispatcher.BeginInvoke(new Action(async delegate{if(closed||!listening.IsEnabled)return;StopListening();input.Text=e.Result.Text;if(e.Result.Confidence>=.65)await Execute(input.Text);else{Say("Revisá la orden reconocida y pulsá Enviar.");ShowInput();}}));};}StopVoice();completion.Stop();recognizer.RecognizeAsync(RecognizeMode.Single);microphone.Content="Escuchando · detener";listening.Start();desktop.SetAssistantListening(true);}catch(Exception ex){StopListening();Say(ex.Message);ShowInput();}
        }
        private void StopListening(){listening.Stop();desktop.SetAssistantListening(false);if(recognizer!=null)try{recognizer.RecognizeAsyncCancel();}catch{}microphone.Content="Hablar";}
        private void StopVoice(){if(speaker!=null)speaker.SpeakAsyncCancelAll();desktop.SetAssistantSpeaking(false);}
        internal void StopAllVoice(){++operation;busy=false;pending=null;confirm.Visibility=Visibility.Collapsed;appearance.Stop();completion.Stop();StopListening();StopVoice();desktop.SetAssistantVisual(AssistantStage.Hidden,null);}
    }
}
